// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(this), address(this));
    }

    function _run(address _distributor) internal {
        vm.assume(true);
        try c.setRewardDistributor(_distributor) {} catch { return; }
        assertTrue(c.rewardDistributor() == _distributor);
    }

    function testFuzz_run(address _distributor) public {
        _run(_distributor);
    }

    receive() external payable {}
}
